javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let conditionalParams = {};
	const viewType = api?.state?.selectedRuleType;
	// Find out the rule type, to decide which view to direct to
	if(viewType == "gen_ai_agent" || viewType == "gen_ai_workflow") {
		conditionalParams = {
			"viewType" : viewType
		}
	}

	return {
		route: "results",
		fields: {
			"requestId": event.payload.data.output.requestId
		},
		params: conditionalParams,
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null
	};
})

